/* 地方生活：九县分别存账，不把本人寄物、公用物资和NPC私产混用。 */
(()=>{'use strict';
const S=XTSandbox,W=XTWorld36,C=XTContent47,V=S.view,D=XTCounty56Data;
const old={scene:renderScene,newGame,restore,dispatch:S.dispatch,mapRooms:XTMap45.rooms,placeName,locationLabel:W.locationLabel};
const defs=Object.fromEntries(Object.entries(D.regions).flatMap(([region,r])=>r.nodes.map(n=>[n.id,{...n,region}])));
const object=x=>!!x&&typeof x==='object'&&!Array.isArray(x);
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let message='';
const region=()=>G?.currentRegion48?.id||G?.birthContext?.id;
placeName=function(key){return G?.currentRegion48?.places?.[key||G.place]||old.placeName(key);};
W.locationLabel=function(){const r=G?.currentRegion48;if(r?.id&&r.id!==G.birthContext?.id)return [r.country,r.state,r.prefecture,r.county,placeName(G.place)].filter(Boolean).join(' · ');return old.locationLabel();};
const state=()=>G?.county56||null;
const nodeState=id=>state()?.regions?.[defs[id]?.region]?.nodes?.[id]||null;
function living(id){const n=G.world36?.people?.[id];return !!n&&n.alive!==false&&(!Number.isFinite(n.birth)||!Number.isFinite(n.life)||S.now()<n.birth+n.life*360);}
function present(n){return living(n.npc.id)&&W.present(n.npc.id);}
function seed(){if(!G?.world36?.people)return;if(!G.county56)G.county56={version:1,peopleSeeded:false,regions:{},transfers:[]};const s=state();for(const n of Object.values(defs)){S.actors[n.npc.id]={name:n.npc.name,role:n.npc.role,place:n.place,room:n.id};if(!s.peopleSeeded&&!G.world36.people[n.npc.id])G.world36.people[n.npc.id]={...n.npc,layer:n.npc.realm<0?0:1,birth:CFG.eraStart*360-n.npc.age*360,place:n.place,room:n.id,region56:n.region,alive:true,source:'县域独有地方生活人物'};}s.peopleSeeded=true;}
function writable(n){const s=state();s.regions[n.region]||={nodes:{}};return s.regions[n.region].nodes[n.id]||=( {supplied:0,deposits:{},choice:null,journal:[]} );}
function record(s,text){s.journal.push({day:S.now(),text});s.journal=s.journal.slice(-24);addLog('地方往来 · '+text,'mute');}
function remember(n,text){if(!present(n))return;const r=W.relation(n.npc.id);r.history.unshift({day:S.now(),text});r.history=r.history.slice(0,24);}
function day(){const r=advanceDays(1,{act:'地方生活',rate:0,incomeMul:0},{stopOnEvent:true});if(r.died){die('寿元耗尽');return false;}if(r.event){startEvent(r.event);return false;}return r.days===1;}
function transact(fn){const ok=C.atomic(fn);if(!ok)message=C.takeFailure()||'本次地方账目未能保存，钱物和日期已撤回。';render();return ok;}
function dispatch(type,arg=''){message='';if(!systemReady())return false;const [id,choice]=String(arg).split(':'),n=defs[id];if(!n||n.region!==region()||n.place!==G.place||S.state().room!==id){message='须到实际所在地，不能隔县办理。';return false;}const item=n.service.item;
 if(type==='mediate'){if(n.service.kind!=='mediate'||!['help','keep'].includes(choice)||nodeState(id)?.choice===choice)return false;if(!present(n)){message='经办人不在这里或已故，不能远程与其商议。';render();return false;}return transact(()=>{if(!day())return;if(!present(n)){message='经办人已无法继续商议，本次没有议定新安排。';return;}const s=writable(n);s.choice=choice;G.world36.people[n.npc.id].goal=n.responses[choice];record(s,n.responses[choice]);remember(n,n.responses[choice]);});}
 if(type==='supply'){if(n.service.kind!=='supply'||(G.inventory[item]||0)<1){message='需要本人行囊中的'+(BAG_ITEMS[item]?.name||item)+'一份。';render();return false;}if((nodeState(id)?.supplied||0)>=Number.MAX_SAFE_INTEGER){message='备料记录已满，暂不能追加。';render();return false;}return transact(()=>{if(!day())return;if((G.inventory[item]||0)<1)return;G.inventory[item]--;const s=writable(n);s.supplied++;remember(n,n.responses.help);record(s,present(n)?n.responses.help:'你将一份'+BAG_ITEMS[item].name+'记入'+n.label+'的公用备料；没有以故人的名义领取赏钱。');});}
 if(type==='deposit'||type==='withdraw'){if(n.service.kind!=='store')return false;const owner=G.world36.playerId,has=nodeState(id)?.deposits?.[owner]||0;if(type==='deposit'&&(G.inventory[item]||0)<1||type==='withdraw'&&has<1){message=type==='deposit'?'本人行囊没有这份寄物。':'本人寄格里没有可取回的份额。';render();return false;}if(type==='deposit'&&has>=Number.MAX_SAFE_INTEGER||type==='withdraw'&&(G.inventory[item]||0)>=Number.MAX_SAFE_INTEGER)return false;return transact(()=>{const s=writable(n);if(type==='deposit'){G.inventory[item]--;s.deposits[owner]=(s.deposits[owner]||0)+1;}else{s.deposits[owner]--;G.inventory[item]=(G.inventory[item]||0)+1;}remember(n,n.responses[type==='deposit'?'help':'keep']);record(s,present(n)?n.responses[type==='deposit'?'help':'keep']:'你按本人寄格账'+(type==='deposit'?'存入':'取回')+'一份'+BAG_ITEMS[item].name+'；其他人的物件没有动。');});}
 if(type==='return'){if(!present(n)){message='经办人不在这里或已故，设施与留存记录仍可查看。';render();return false;}return transact(()=>{if(day()&&present(n))record(writable(n),n.responses.return);});}
 return false;}
function inherit(from,to){const s=state();if(!s||s.transfers.some(x=>x.from===from&&x.to===to))return;for(const r of Object.values(s.regions))for(const n of Object.values(r.nodes)){const amount=n.deposits[from]||0;if(amount){n.deposits[to]=(n.deposits[to]||0)+amount;delete n.deposits[from];record(n,'本人寄存份额随已确认的家业接续转交后人，公用备料与旁人寄物未动。');}}s.transfers.push({from,to});}
function button(label,type,id,off=false){return '<button type="button" class="sb-btn" data-county56="'+type+'" data-node56="'+id+'" '+(off?'disabled':'')+'>'+esc(label)+'</button>';}
function panel(id=S.state().room){const n=defs[id];if(!n||n.region!==region()||n.place!==G.place)return '';const s=nodeState(id),owner=G.world36.playerId,stock=s?.deposits?.[owner]||0,alive=present(n);let controls='';
 if(n.service.kind==='supply')controls=button('添本人材料一份 · 1日','supply',id,(G.inventory[n.service.item]||0)<1)+'<p>已入公用备料 '+(s?.supplied||0)+' 份；不换赏钱，不产生公产所有权。</p>';
 if(n.service.kind==='store')controls=button('存入本人一份','deposit',id,(G.inventory[n.service.item]||0)<1)+button('取回本人一份','withdraw',id,stock<1)+'<p>本人寄存 '+stock+' 份 · 无额外寄存费，按实存取回。</p>';
 if(n.service.kind==='mediate')controls=button('参与商议 · 1日','mediate',id+':help',!alive||s?.choice==='help')+button('保留各自安排 · 1日','mediate',id+':keep',!alive||s?.choice==='keep')+'<p>'+(s?.choice?esc(n.responses[s.choice]):'尚无你参与的协商记录，随时可以先走。')+'</p>';
 return '<section class="life56-card county56-card"><small>'+esc(D.regions[n.region].title)+' · 地方生活</small><h3>'+esc(n.service.title)+'</h3><p>'+esc(n.description)+'</p><p>'+esc(alive?n.npc.name+' · '+n.npc.role:living(n.npc.id)?'经办人目前在别处；本人寄物与公共记录仍留在这里。':G.world36.people[n.npc.id]?'原经办人已故；设施与记录仍在。':'经办人资料未核定，设施与记录仍在。')+'</p><p>'+(!alive?'留存告示：':'')+esc(n.service.text)+'</p><div class="life56-actions">'+controls+'</div>'+(message?'<p class="life56-notice" role="status">'+esc(message)+'</p>':'')+'<details><summary>物品归属与往来</summary><p>'+esc(n.ownership)+'</p>'+((s?.journal||[]).map(h=>'<p>'+esc(h.text)+'</p>').join('')||'<p>尚无本人经办记录。</p>')+'</details></section>';}
function decorate(){if(!G||G.mode!=='idle'||V.tab!=='scene')return;const n=defs[S.state().room];if(!n||n.region!==region())return;const scene=document.getElementById('scene'),scroll=scene?.querySelector('.sb-scroll');if(!scroll?.parentNode||scroll.querySelector('.county56-card'))return;const desc=scene.querySelector('.next-hero-copy p'),saved=nodeState(n.id);if(desc)desc.textContent=present(n)?saved?.choice?n.responses[saved.choice]:n.description:living(n.npc.id)?'经办人暂在别处，'+n.label+'与本人寄物记录仍在。':'原经办人已故或资料未核定，'+n.label+'及本人寄物、公共备料记录仍留在原处。';const host=document.createElement('div');host.innerHTML=panel();(scroll.querySelector('.next-main')||scroll).append(host);host.querySelectorAll('[data-county56]').forEach(b=>b.onclick=()=>dispatch(b.dataset.county56,b.dataset.node56));}
XTMap45.rooms=function(base){const rs=old.mapRooms(base),nodes=D.regions[region()]?.nodes||[];return [...rs,...nodes.filter(n=>n.place===G.place).map(n=>[n.id,n.label])];};
S.dispatch=function(a,arg){if(a?.startsWith('c56:'))return dispatch(a.slice(4),arg);return old.dispatch(a,arg);};
renderScene=function(...a){const out=old.scene(...a);decorate();return out;};
newGame=function(...a){const carried=a.length>=4&&G?.mode==='dead'&&state()?JSON.parse(JSON.stringify(state())):null;for(const n of Object.values(defs))delete S.actors[n.npc.id];const out=old.newGame(...a);if(carried)G.county56=carried;seed();return out;};
restore=function(raw){try{const s=JSON.parse(raw).county56;if(s!=null){if(!object(s)||s.version!==1||!object(s.regions)||s.peopleSeeded!==true||!Array.isArray(s.transfers)||s.transfers.some(t=>!object(t)||typeof t.from!=='string'||typeof t.to!=='string'||t.from===t.to))throw Error('地方账目无效');for(const [rid,r]of Object.entries(s.regions)){if(!D.regions[rid]||!object(r)||!object(r.nodes))throw Error('地区无效');for(const [id,n]of Object.entries(r.nodes)){if(defs[id]?.region!==rid||!object(n)||!Number.isSafeInteger(n.supplied)||n.supplied<0||!object(n.deposits)||Object.values(n.deposits).some(v=>!Number.isSafeInteger(v)||v<0)||!Number.isSafeInteger(Object.values(n.deposits).reduce((a,b)=>a+b,0))||!['help','keep',null].includes(n.choice)||!Array.isArray(n.journal)||n.journal.length>24||n.journal.some(h=>!object(h)||!Number.isSafeInteger(h.day)||typeof h.text!=='string'))throw Error('寄存或公用物资无效');}}}}catch(e){XTEconomy40.lastRestoreError='县域寄存或地方记录无效，当前存档保留。';return false;}const ok=old.restore(raw);if(ok)seed();return ok;};
window.XTCounty56={state,seed,region,defs,nodeState,living,dispatch,inherit,panel};if(G)seed();
})();
